    cnt=Counter(x for r in inp for x in r)
    border=max(cnt,key=cnt.get)
    cols=[c for c in range(W) if any(inp[r][c]==border for r in range(H))]
    if fw is None: fw=max(cols)+1
    interior=W-fw
    out=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(fw): out[r][c]=inp[r][c]
