        cells=[(r,c) for r in range(H) for c in range(fw,W) if inp[r][c]==v]
        rs=[r for r,_ in cells]; cs=[c for _,c in cells]
        h_=max(rs)-min(rs)+1; w_=max(cs)-min(cs)+1
        shapes[v]=(min(rs),min(cs),h_,w_,cells)
    # sort: width desc, then top row asc
    order=sorted(shapes.values(), key=lambda s:(-s[3],s[0]))
    start=min(rs for rs in () or [s[0] for s in order]) if False else None
    tops=[s[0] for s in order]
    pos=[]
    cur=0
    for h_,w_,cells in [(s[2],s[3],s[4]) for s in order]:
        pos.append(cur)
        cur+=h_+1
    for (rt,rc,ht,wd,cl),p in zip([(s[0],s[1],s[2],s[3],s[4]) for s in order],pos):
        for r,c in cl:
            rr=p+(r-rt); cc=(c-fw)
