    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def f(I):
    H=len(I); W=len(I[0])
    cnt=Counter()
    for row in I:
        for v in row: cnt[v]+=1
    fc=max(cnt,key=cnt.get)
    sep=None
    for c in range(W):
        col_ok=all(I[r][c] in (0,fc) for r in range(H))
        if sep is None or col_ok: sep=c
    sep=max(c for c in range(W) if all(I[r][c] in (0,fc) for r in range(H)))
    fw=sep
    seen=[[False]*W for _ in range(H)]; items=[]
    for rr in range(H):
        for cc in range(W):
            if I[rr][cc]!=fc and I[rr][cc]!=0 and not seen[rr][cc]:
                col=I[rr][cc]; st=[(rr,cc)]; seen[rr][cc]=True; comp=[]
                while st:
                    p=st.pop(); comp.append(p)
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=p[0]+dr,p[1]+dc
                            if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and I[nr][nc]==col:
                                seen[nr][nc]=True; st.append((nr,nc))
                tr=min(p[0] for p in comp)
                items.append((col,tr,comp))
    out=[[0]*fw for _ in range(H)]
    for col,tr,comp in reversed(items):
        tc=min(p[1] for p in comp)
        shift=1-tc
        for r,c in comp:
            out[r][c+shift]=col
    for r in range(H):
        for c in range(fw):
            if out[r][c]==0: out[r][c]=fc
    return out

