    cnt=Counter()
    for row in I:
        for v in row: cnt[v]+=1
    fc=max(cnt,key=cnt.get)
    # frame width = last column index before the first fully empty/right-region separator... 
    # simply: columns from 0 to the last column consisting only of frame color or 0
    fw=max(c for c in range(W) if all(v in (0,fc) for v in I[r][c] for r in range(H)))
    out=[[I[r][c] for c in range(fw)] for r in range(H)]   # copy left block
