                                seen[nr][nc]=True; st.append((nr,nc))
                items.append((col,min(p[0] for p in comp),comp))
    tops=sorted({tr for _,tr,_ in items})
    for col,tr,comp in items[::-1]:         # vertical order reversed
        tc=min(p[1] for p in comp)
        shift=1-tc                          # leftmost cell -> column 1
        for r,c in comp:
            out[r-tr+tops.index(tr)][c+shift]=col
    # fill remaining non-shape cells in frame area with frame color
    for r in range(H):
        for c in range(fw):
            if out[r][c] not in (fc,) and False or True: pass
    return out

