                                seen[nr][nc]=True; st.append((nr,nc))
                items.append((col,comp))
    out=[[fc]*W for _ in range(H)]
    nb=len(bands)
    for idx,(r0,r1) in enumerate(bands):
        band_items=[i for i in items if r0<=min(p[0] for p in i[1]) and max(p[0] for p in i[1])<=r1]
