                out[p[0]][p[1]]=col             # keep original coordinates
        # clear original shapes within this band from source
        for col,comp in band_items:
            for p in comp:
                out[p[0]][p[1]]=0
        for col,comp in items:
            for p in comp:
                pass
    return [[0]*W for _ in range(H)]   # placeholder -- write final clean later

